select jsonb_agg(jsonb_build_object('name',rolname,'superuser',rolsuper,'inherit',rolinherit,'create_role',rolcreaterole,'create_db',rolcreatedb,'bypass_rls',rolbypassrls,'memberships',(select coalesce(jsonb_agg(r.rolname order by r.rolname),'[]')from pg_auth_members m join pg_roles r on r.oid=m.roleid where m.member=p.oid))order by rolname)from pg_roles p where rolname in('postgres','supabase_admin','supabase_auth_admin','supabase_storage_admin','anon','authenticated','service_role');
